/* @autogenerated */
import {
  TenantConfigFilter,
  TenantConfigProjection,
} from 'app/features/access/tenant-config/model/tenant-config.model';
import { TenantConfigRepository } from 'app/features/access/tenant-config/repository/tenant-config-repository.service';
import { FormControl } from '@angular/forms';
import { Shift } from '@common/data/repository/repository.model';
import { input, effect, Component } from '@angular/core';

@Component({
  selector: 'tenant-config-view-list',
  templateUrl: './tenant-config-view-list.component.html',
  styleUrls: ['./tenant-config-view-list.component.scss'],
  standalone: false,
})
export class TenantConfigViewListComponent {
  filters = input<TenantConfigFilter>();
  actionName = input<string>('tenant-config');
  fixed = input<{ [key: string]: any }>();
  hidden = input<{ [key: string]: any }>();
  search = new FormControl<any>(undefined);
  list: Shift<TenantConfigProjection[], TenantConfigFilter>;

  constructor(repository: TenantConfigRepository) {
    this.list = repository.projections(['tenant']);
    effect(() => {
      setTimeout(() => this.makeSearch());
    });
  }
  makeSearch() {
    const result = { limit: 10 } as any;
    const filter = this.search.value;
    const external = this.filters();
    if (external?.search) {
      result.search = external.search;
    }
    if (external?.tenants) {
      result.tenants = external.tenants;
    }
    if (filter?.search) {
      result.search = filter.search;
    }
    if (filter?.tenants?.$ref) {
      result.tenants = filter.tenants.$ref;
    }
    this.list.fetch(result);
  }

  next() {
    this.list.next();
  }

  reload() {
    this.list.reset();
  }

  prev() {
    console.log('PREV');
  }
}
